    86|  "i will return proof",
    87|  "i'll check",
    88|  "i will check",
    89|  "i'll look",
    90|  "i will look",
    91|  "i'll review",
    92|  "i will review",
    93|  "let me check",
    94|  "let me look",
    95|  "let me inspect",
    96|  "let me review",
    97|  "let me see",
    98|  'one moment',
    99|  'one sec',
   100|  'just a moment',
