```typescript
export function validateStructuredJobEvidence(job: IVXIAJobEvidence): {
  valid: boolean;
  state: IVXIAState;
  reason: string | null;
  contradictions: string[];
} {
  const allowedStatuses: IVXIAJobStatus[] = [...];
  if (!allowedStatuses.includes(job.status)) {
    return { valid: false, state: 'UNVERIFIED', reason: `Invalid structured status: ${job.status}`, contradictions: [] };
  }
  if (!job.taskId || job.taskId.length < 4) {
    return { valid: false, state: 'UNVERIFIED', reason: 'Missing taskId', contradictions: [] };
  }
  if (job.status === 'COMPLETED' && job.blockedReason) {
    return { valid: false, state: 'UNVERIFIED', reason: 'COMPLETED job has blockedReason', contradictions: ['COMPLETED + blockedReason'] };
  }
  if (job.status === 'COMPLETED' && job.filesChanged.length === 0) {
    return { valid: false, state: 'UNVERIFIED', reason: 'COMPLETED code-change task has no filesChanged', contradictions: [] };
  }

  // Map job status to gate state
  const stateMap: Record<IVXIAJobStatus, IVXIAState> = {
    QUEUED: 'RUNNING',
    CLAIMED: 'RUNNING',
    RUNNING: 'RUNNING',
    TESTING: 'RUNNING',
    WAITING_OWNER: 'WAITING_OWNER',
    BLOCKED: 'BLOCKED',
    FAILED: 'FAILED',
    COMPLETED: 'VERIFIED',
    CANCELLED: 'BLOCKED',
  };

  return { valid: true, state: stateMap[job.status], reason: null, contradictions: [] };
}
