  if (job.status === 'BLOCKED') {
    if (!job.blockedReason && !job.error) missing.push('exact blocker or error');
    if (!job.completedSteps || job.completedSteps.length === 0) missing.push('completed steps');
  }

  if (job.status === 'COMPLETED') {
    if (!job.tests || !job.tests.run) missing.push('tests');
    if (!job.commitSha && job.filesChanged.length > 0) missing.push('commitSha when code changed');
    // The user says: "Do not require 'files changed' for every blocked task. Do require it for a completed code-change task."
    if (job.filesChanged.length === 0) missing.push('filesChanged');
  }

  if (job.status === 'COMPLETED' && job.blockedReason) {
    return { valid: false, state: 'UNVERIFIED', reason: 'COMPLETED job cannot have blockedReason', contradictions: ['COMPLETED + blockedReason'], missing };
  }

  // ...
